<?php namespace App\Models; use Illuminate\Database\Eloquent\Model;
class Pemesanan extends Model { protected $table='Rental_kendaraan_pemesanan'; protected $primaryKey='id_pemesanan'; public function getRouteKeyName(){return $this->primaryKey;} protected $fillable=['id_customer','id_armada','id_sopir','tanggal_sewa','durasi','total_biaya','layanan','status','alamat_antar']; protected $casts=['tanggal_sewa'=>'date','total_biaya'=>'decimal:2']; public function customer(){return $this->belongsTo(Customer::class,'id_customer','id_customer');} public function armada(){return $this->belongsTo(Armada::class,'id_armada','id_armada');} public function sopir(){return $this->belongsTo(Sopir::class,'id_sopir','id_sopir');} public function pembayaran(){return $this->hasOne(Pembayaran::class,'id_pemesanan','id_pemesanan');} }
